<?php
if(!is_file(__DIR__.'/config.php')){header('Location: install.php');exit;}require __DIR__.'/bootstrap.php';if(me()){header('Location: game.php');exit;}$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$u=trim($_POST['username']??'');$pw=(string)($_POST['password']??'');$tribe=(int)($_POST['tribe']??1);$register=($_POST['mode']??'login')==='register';if($register){if(strlen($u)<3||strlen($pw)<6)throw new Exception('Naam minimaal 3 en wachtwoord minimaal 6 tekens.');if(isset(tribes()[$tribe])===false)throw new Exception('Ongeldige stam.');if(one('SELECT id FROM op_players WHERE username=?',[$u]))throw new Exception('Speler bestaat al.');q('INSERT INTO op_players(username,password_hash,tribe,created_at) VALUES(?,?,?,?)',[$u,password_hash($pw,PASSWORD_DEFAULT),$tribe,now()]);$id=(int)db()->lastInsertId();$x=0;$y=0;for($i=0;$i<100;$i++){$x=rand(-20,20);$y=rand(-20,20);if(!one('SELECT id FROM op_villages WHERE x=? AND y=?',[$x,$y]))break;}q('INSERT INTO op_villages(owner_id,name,x,y,last_tick,created_at) VALUES(?,?,?,?,?,?)',[$id,$u.'s dorp',$x,$y,now(),now()]);$vid=(int)db()->lastInsertId();for($s=1;$s<=18;$s++){ $t=$s<=4?1:($s<=8?2:($s<=12?3:4));q('INSERT INTO op_fields(village_id,slot,type,level) VALUES(?,?,?,1)',[$vid,$s,$t]);}for($s=19;$s<=40;$s++)q('INSERT INTO op_buildings(village_id,slot,type,level) VALUES(?,?,0,0)',[$vid,$s]);q('UPDATE op_buildings SET type=15,level=1 WHERE village_id=? AND slot=27',[$vid]);q('INSERT INTO op_hero(player_id,village_id) VALUES(?,?)',[$id,$vid]);q('INSERT INTO op_quests(player_id,quest_key) VALUES(?,?)',[$id,'first_field']);$_SESSION['uid']=$id;$_SESSION['village_id']=$vid;header('Location: game.php');exit;}else{$p=one('SELECT * FROM op_players WHERE username=?',[$u]);if(!$p||!password_verify($pw,$p['password_hash']))throw new Exception('Onjuiste login.');$_SESSION['uid']=$p['id'];$v=one('SELECT id FROM op_villages WHERE owner_id=? ORDER BY id LIMIT 1',[$p['id']]);$_SESSION['village_id']=$v['id'];header('Location: game.php');exit;}}catch(Throwable $e){$err=$e->getMessage();}}
